  "inlineSchema": "// Bodapp Prisma schema — v1 core data model.\n// See plan Task 1. Multi-phone invitations via Invitation.acceptedPhones\n// (couple/family share one link); OTP validated against that list before sending.\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\nenum RSVPStatus {\n  pending\n  confirmed\n  declined\n  maybe\n}\n\nenum UserRole {\n  couple\n  planner\n}\n\nenum TaskStatus {\n  todo\n  in_progress\n  done\n  blocked\n}\n\nenum TaskPriority {\n  low\n  medium\n  high\n}\n\nenum TaskCategory {\n  legal // juzgado, traslado expediente, cita para casarse, documentación\n  vendors // catering, fotografía, música, flores, transporte, venue\n  timing // ensayo, llegada invitados, cóctel, cena, discursos, primer baile\n  gifts // regalo especiales, lista de bodas, agradecimientos, detalles\n}\n\nmodel Wedding {\n  id          String    @id @default(uuid())\n  slug        String    @unique\n  coupleNameA String\n  coupleNameB String\n  bankAccount String? // couple's IBAN, shown on invitations\n  date        DateTime?\n  locale      String    @default(\"es\")\n  createdAt   DateTime  @default(now())\n\n  users       User[]\n  guests      Guest[]\n  tables      Table[]\n  tasks       Task[]\n  invitations Invitation[]\n  templates   InvitationTemplate[]\n  decorations Decoration[]\n  photos      Photo[]\n\n  @@index([slug])\n}\n\nmodel User {\n  id           String   @id @default(uuid())\n  weddingId    String\n  email        String   @unique\n  passwordHash String\n  role         UserRole @default(couple)\n  createdAt    DateTime @default(now())\n\n  wedding Wedding @relation(fields: [weddingId], references: [id])\n\n  @@index([weddingId])\n}\n\nmodel Guest {\n  id                  String     @id @default(uuid())\n  weddingId           String\n  fullName            String\n  alias               String?\n  relationshipContext String? // \"de qué los conocemos\"\n  phone               String // E.164 primary phone\n  allergies           String[]   @default([])\n  musicPrefs          String[]   @default([])\n  paperInvitation     Boolean    @default(false)\n  plusOneAllowed      Boolean    @default(false)\n  plusOneName         String?\n  rsvpStatus          RSVPStatus @default(pending)\n  tableId             String?\n  seatNumber          Int? // concrete seat at their table (seating map); null when unassigned/not numbered\n  notes               String?\n  invitationToken     String     @unique\n  createdAt           DateTime   @default(now())\n  updatedAt           DateTime   @updatedAt\n\n  table   Table?          @relation(fields: [tableId], references: [id])\n  wedding Wedding         @relation(fields: [weddingId], references: [id])\n  from    GuestRelation[] @relation(\"guestFrom\")\n  to      GuestRelation[] @relation(\"guestTo\")\n\n  @@index([weddingId])\n  @@index([tableId])\n}\n\n// Relationships between guests (partner, sibling, \"doesn't get along\", etc.)\nmodel GuestRelation {\n  id           String @id @default(uuid())\n  weddingId    String\n  guestAId     String\n  guestBId     String\n  relationType String // partner | sibling | parent | child | friend | colleague | doesnt_get_along | other\n\n  guestA Guest @relation(\"guestFrom\", fields: [guestAId], references: [id])\n  guestB Guest @relation(\"guestTo\", fields: [guestBId], references: [id])\n\n  @@index([weddingId])\n  @@index([guestAId])\n  @@index([guestBId])\n}\n\n// An invitation link may cover several people (couple/family).\n// acceptedPhones is the allowlist validated BEFORE sending an OTP.\nmodel Invitation {\n  id             String   @id @default(uuid())\n  weddingId      String\n  title          String // e.g. \"Familia García\"\n  acceptedPhones String[] @default([]) // MULTIPLE valid phones\n  createdAt      DateTime @default(now())\n\n  wedding  Wedding   @relation(fields: [weddingId], references: [id])\n  otpCodes OtpCode[]\n\n  @@index([weddingId])\n}\n\n// One-time OTP issued for a phone against an invitation allowlist. Only the\n// hashed code is stored (never plaintext); see src/lib/otp.ts.\n// @see Task 9 — public invitation portal\nmodel OtpCode {\n  id           String    @id @default(uuid())\n  invitationId String\n  phone        String // normalized E.164 phone that requested the code\n  codeHash     String // sha256 hex of the 6-digit code (never plaintext)\n  attempts     Int       @default(0) // failed verify attempts\n  expiresAt    DateTime\n  consumedAt   DateTime?\n  createdAt    DateTime  @default(now())\n\n  invitation Invitation @relation(fields: [invitationId], references: [id])\n\n  @@index([invitationId, phone])\n  @@index([phone, expiresAt])\n}\n\nmodel Table {\n  id        String @id @default(uuid())\n  weddingId String\n  name      String\n  shape     String @default(\"round\") // round | rectangle\n  capacity  Int    @default(8)\n  positionX Float  @default(0)\n  positionY Float  @default(0)\n\n  wedding Wedding @relation(fields: [weddingId], references: [id])\n  guests  Guest[]\n\n  @@index([weddingId])\n}\n\n// Decoration & gift layer items placed on the seating canvas.\nmodel Decoration {\n  id        String  @id @default(uuid())\n  weddingId String\n  kind      String // centerpiece | giftTable | photoWall | danceFloor | other\n  label     String?\n  positionX Float   @default(0)\n  positionY Float   @default(0)\n\n  wedding Wedding @relation(fields: [weddingId], references: [id])\n\n  @@index([weddingId])\n}\n\nmodel Task {\n  id          String       @id @default(uuid())\n  weddingId   String\n  title       String\n  description String?\n  category    TaskCategory\n  priority    TaskPriority @default(medium)\n  status      TaskStatus   @default(todo)\n  dueDate     DateTime?\n  assigneeId  String?\n  notes       String?\n  createdAt   DateTime     @default(now())\n\n  wedding Wedding @relation(fields: [weddingId], references: [id])\n\n  @@index([weddingId])\n  @@index([status])\n}\n\nmodel InvitationTemplate {\n  id          String    @id @default(uuid())\n  weddingId   String\n  version     Int       @default(1)\n  content     Json // { text, images, colors, musicUrl, ... }\n  publishedAt DateTime?\n  createdAt   DateTime  @default(now())\n\n  wedding Wedding @relation(fields: [weddingId], references: [id])\n\n  @@index([weddingId])\n}\n\n// Couple photos (v1). Guest uploads deferred to v1.1.\nmodel Photo {\n  id        String   @id @default(uuid())\n  weddingId String\n  filename  String\n  mimeType  String\n  size      Int\n  createdAt DateTime @default(now())\n\n  wedding Wedding @relation(fields: [weddingId], references: [id])\n\n  @@index([weddingId])\n}\n",
